{
  "application": "data-visualization",
  "case_id": "case-education-investment-vs-outcomes-30-countries",
  "language": "en",
  "style": {
    "theme": "editorial",
    "audience": "researchers and policy makers",
    "tone": "analytical, publication-ready, layered"
  },
  "goal": [
    {
      "id": "nonlinear-spending-outcomes",
      "insight": "Show the relationship between education spending as a share of GDP and multiple outcome metrics across 30 countries, making any non-linear or scattered patterns visually prominent"
    },
    {
      "id": "high-spenders-mixed-results",
      "insight": "Highlight countries that spend heavily on education but show divergent outcomes across PISA scores, university enrollment, and youth unemployment"
    },
    {
      "id": "efficiency-outliers",
      "insight": "Emphasize countries that achieve strong educational outcomes (high PISA, high enrollment, low youth unemployment) despite moderate or low spending levels"
    },
    {
      "id": "youth-unemployment-disconnect",
      "insight": "Visually contrast youth unemployment rates against education spending and PISA scores to reveal where labor market outcomes decouple from educational investment"
    },
    {
      "id": "multi-metric-encoding",
      "insight": "Encode education spending on the x-axis, PISA score as y-axis, bubble size as university enrollment rate, and bubble color as youth unemployment rate, with country labels on notable cases"
    }
  ]
}

